// 20 px icon paths from Microsoft Fluent UI System Icons.
// https://github.com/microsoft/fluentui-system-icons (MIT)
use std::sync::LazyLock;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Icon {
	Refresh,
	Scan,
	Settings,
	MoreCircle,
	ChevronDown,
	Brightness,
	Wifi,
	WifiOff,
	Bulb,
	BulbFilled,
	Flame,
	Add,
	Subtract,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Command {
	Move(f32, f32),
	Line(f32, f32),
	Horizontal(f32),
	Vertical(f32),
	Curve(f32, f32, f32, f32, f32, f32),
	Close,
}

pub fn commands(icon: Icon) -> &'static [Command] {
	static REFRESH: LazyLock<Vec<Command>> = LazyLock::new(|| parse(REFRESH_PATH));
	static SCAN: LazyLock<Vec<Command>> = LazyLock::new(|| parse(SCAN_PATH));
	static SETTINGS: LazyLock<Vec<Command>> = LazyLock::new(|| parse(SETTINGS_PATH));
	static MORE_CIRCLE: LazyLock<Vec<Command>> = LazyLock::new(|| parse(MORE_CIRCLE_PATH));
	static CHEVRON_DOWN: LazyLock<Vec<Command>> = LazyLock::new(|| parse(CHEVRON_DOWN_PATH));
	static BRIGHTNESS: LazyLock<Vec<Command>> = LazyLock::new(|| parse(BRIGHTNESS_PATH));
	static WIFI: LazyLock<Vec<Command>> = LazyLock::new(|| parse(WIFI_PATH));
	static WIFI_OFF: LazyLock<Vec<Command>> = LazyLock::new(|| parse(WIFI_OFF_PATH));
	static BULB: LazyLock<Vec<Command>> = LazyLock::new(|| parse(BULB_PATH));
	static BULB_FILLED: LazyLock<Vec<Command>> = LazyLock::new(|| parse(BULB_FILLED_PATH));
	static FLAME: LazyLock<Vec<Command>> = LazyLock::new(|| parse(FLAME_PATH));
	static ADD: LazyLock<Vec<Command>> = LazyLock::new(|| parse(ADD_PATH));
	static SUBTRACT: LazyLock<Vec<Command>> = LazyLock::new(|| parse(SUBTRACT_PATH));

	match icon {
		Icon::Refresh => REFRESH.as_slice(),
		Icon::Scan => SCAN.as_slice(),
		Icon::Settings => SETTINGS.as_slice(),
		Icon::MoreCircle => MORE_CIRCLE.as_slice(),
		Icon::ChevronDown => CHEVRON_DOWN.as_slice(),
		Icon::Brightness => BRIGHTNESS.as_slice(),
		Icon::Wifi => WIFI.as_slice(),
		Icon::WifiOff => WIFI_OFF.as_slice(),
		Icon::Bulb => BULB.as_slice(),
		Icon::BulbFilled => BULB_FILLED.as_slice(),
		Icon::Flame => FLAME.as_slice(),
		Icon::Add => ADD.as_slice(),
		Icon::Subtract => SUBTRACT.as_slice(),
	}
}

/// Parse the subset of SVG path syntax used by Fluent icons: absolute M, L,
/// H, V, C and Z commands. The source paths contain no arcs or relative
/// commands.
fn parse(data: &str) -> Vec<Command> {
	let mut output = Vec::new();
	let mut command = None;
	let mut numbers = Vec::new();
	let bytes = data.as_bytes();
	let mut index = 0;
	while index < bytes.len() {
		let ch = bytes[index] as char;
		if ch.is_ascii_alphabetic() {
			if let Some(previous) = command {
				flush(previous, &mut numbers, &mut output);
			}
			command = Some(ch);
			index += 1;
		} else if ch.is_ascii_digit() || ch == '-' || ch == '+' || ch == '.' {
			let start = index;
			index += 1;
			while index < bytes.len() {
				let current = bytes[index] as char;
				if current.is_ascii_digit()
					|| current == '.'
					|| current == 'e'
					|| current == 'E'
					|| ((current == '-' || current == '+')
						&& matches!(bytes[index - 1], b'e' | b'E'))
				{
					index += 1;
				} else {
					break;
				}
			}
			if let Ok(value) = data[start..index].parse::<f32>() {
				numbers.push(value);
			}
		} else {
			index += 1;
		}
	}
	if let Some(previous) = command {
		flush(previous, &mut numbers, &mut output);
	}
	output
}

fn flush(command: char, numbers: &mut Vec<f32>, output: &mut Vec<Command>) {
	match command {
		'M' => {
			if numbers.len() >= 2 {
				output.push(Command::Move(numbers[0], numbers[1]));
				for pair in numbers[2..].as_chunks::<2>().0 {
					output.push(Command::Line(pair[0], pair[1]));
				}
			}
		}
		'L' => {
			for pair in numbers.as_chunks::<2>().0 {
				output.push(Command::Line(pair[0], pair[1]));
			}
		}
		'H' => {
			for value in numbers.iter() {
				output.push(Command::Horizontal(*value));
			}
		}
		'V' => {
			for value in numbers.iter() {
				output.push(Command::Vertical(*value));
			}
		}
		'C' => {
			for values in numbers.as_chunks::<6>().0 {
				output.push(Command::Curve(
					values[0], values[1], values[2], values[3], values[4], values[5],
				));
			}
		}
		'Z' | 'z' => output.push(Command::Close),
		_ => {}
	}
	numbers.clear();
}

