#[cfg(test)]
mod tests {
	use super::*;

	#[test]
	fn parses_lines() {
		assert_eq!(
			parse("M0 0H24V24Z"),
			vec![
				Command::Move(0.0, 0.0),
				Command::Horizontal(24.0),
				Command::Vertical(24.0),
				Command::Close
			]
		);
	}

	#[test]
	fn every_icon_has_a_path() {
		for icon in [
			Icon::Refresh,
			Icon::Scan,
			Icon::Settings,
			Icon::MoreCircle,
			Icon::ChevronDown,
			Icon::Brightness,
			Icon::Wifi,
			Icon::WifiOff,
			Icon::Bulb,
			Icon::BulbFilled,
			Icon::Flame,
			Icon::Add,
			Icon::Subtract,
		] {
			assert!(!commands(icon).is_empty());
		}
	}
}
